  ('ab-rollout-barbell', 'Barbell rollout', 'Ab_Roller', 'abs', 'barbell', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'plank', 'Geknield met handen op een stang met schijven. Rol naar voren en terug met een stabiele romp.', 60, false),
  ('db-3-4-sit-up', '3/4 Sit-Up', '3_4_Sit-Up', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie down on the floor and secure your feet. Your legs should be bent at the knees. Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position. Flex your hips and spine to raise your torso toward your knees. At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.…', 90, false),
  ('db-advanced-kettlebell-windmill', 'Advanced Kettlebell Windmill', 'Advanced_Kettlebell_Windmill', 'abs', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Clean and press a kettlebell overhead with one arm. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell. Lower yourself as far as possible. Pause for a second and reverse the motion back to the starting position.', 60, false),
  ('db-air-bike', 'Air Bike', 'Air_Bike', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position. Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position. Now simultaneously,…', 90, false),
  ('db-alternate-hammer-curl', 'Alternate Hammer Curl', 'Alternate_Hammer_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells…', 60, false),
  ('db-alternate-heel-touchers', 'Alternate Heel Touchers', 'Alternate_Heel_Touchers', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position. Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. Now go back slowly to the starting position as you inhale. Now…', 60, false),
  ('db-alternate-incline-dumbbell-curl', 'Alternate Incline Dumbbell Curl', 'Alternate_Incline_Dumbbell_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the…', 60, false),
  ('db-alternate-leg-diagonal-bound', 'Alternate Leg Diagonal Bound', 'Alternate_Leg_Diagonal_Bound', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Assume a comfortable stance with one foot slightly in front of the other. Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. It may help to use a line on the ground to guage distance from side to side. Repeat the sequence with the other leg.', 75, false),
  ('db-alternating-cable-shoulder-press', 'Alternating Cable Shoulder Press', 'Alternating_Cable_Shoulder_Press', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Move the cables to the bottom of the tower and select an appropriate weight. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press one side directly over head. After pausing at the top, return to the starting position and repeat on the opposite side.', 90, false),
  ('db-alternating-deltoid-raise', 'Alternating Deltoid Raise', 'Alternating_Deltoid_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'In a standing position, hold a pair of dumbbells at your side. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. Return the weights to your side. On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height. Return the weights to the starting position and continue alternating to the…', 60, false),
  ('db-alternating-floor-press', 'Alternating Floor Press', 'Alternating_Floor_Press', 'chest', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor with two kettlebells next to your shoulders. Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward. Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell. Raise the kettlebell and repeat on the…', 90, false),
  ('db-alternating-hang-clean', 'Alternating Hang Clean', 'Alternating_Hang_Clean', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so. Lower the cleaned kettlebell to a…', 90, false),
  ('db-alternating-kettlebell-press', 'Alternating Kettlebell Press', 'Alternating_Kettlebell_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary . Lower the pressed kettlebell to the starting position and…', 90, false),
  ('db-alternating-kettlebell-row', 'Alternating Kettlebell Row', 'Alternating_Kettlebell_Row', 'back', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles. Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage. Lower…', 60, false),
  ('db-anti-gravity-press', 'Anti-Gravity Press', 'Anti-Gravity_Press', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position. To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement. Return to…', 90, false),
  ('db-around-the-worlds', 'Around The Worlds', 'Around_The_Worlds', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position. Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the…', 90, false),
  ('db-atlas-stone-trainer', 'Atlas Stone Trainer', 'Atlas_Stone_Trainer', 'lower_back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe. Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips. Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by…', 90, false),
  ('db-atlas-stones', 'Atlas Stones', 'Atlas_Stones', 'lower_back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold. Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground. As the stone passes the knees, lap…', 90, false),
  ('db-axle-deadlift', 'Axle Deadlift', 'Axle_Deadlift', 'lower_back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip. With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up…', 90, false),
  ('db-back-flyes-with-bands', 'Back Flyes - With Bands', 'Back_Flyes_-_With_Bands', 'shoulders', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Run a band around a stationary post like that of a squat rack. Grab the band by the handles and stand back so that the tension in the band rises. Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position. As you…', 90, false),
  ('db-backward-drag', 'Backward Drag', 'Backward_Drag', 'quads', 'other', 'custom', array['weight','distance']::text[], 'compound', 'complex', 'Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto. Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.', 90, false),
  ('db-balance-board', 'Balance Board', 'Balance_Board', 'calves', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-calves-compound', 'Place a balance board in front of you. Stand up on it and try to balance yourself. Hold the balance for as long as desired.', 90, false),
  ('db-band-good-morning', 'Band Good Morning', 'Band_Good_Morning', 'hamstrings', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position. Keeping your legs straight, extend through the hips to come to a near vertical position. Ensure that you do not round your back as you go down back to the starting position.', 150, false),
  ('db-band-good-morning-pull-through', 'Band Good Morning (Pull Through)', 'Band_Good_Morning_Pull_Through', 'hamstrings', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position. Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent. Return to the starting position be driving through with the hips to come back to a standing position.', 150, false),
  ('db-band-hip-adductions', 'Band Hip Adductions', 'Band_Hip_Adductions', 'adductors', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-adductors-isolation', 'Anchor a band around a solid post or other object. Stand with your left side to the post, and put your right foot through the band, getting it around the ankle. Stand up straight and hold onto the post if needed. This will be your starting position. Keeping the knee straight, raise your right legs out to the side as far as you can. Return to the starting position and repeat for the desired rep count. Switch sides.', 60, false),
  ('db-band-skull-crusher', 'Band Skull Crusher', 'Band_Skull_Crusher', 'triceps', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head. Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position. Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the…', 60, false),
  ('db-barbell-ab-rollout', 'Barbell Ab Rollout', 'Barbell_Ab_Rollout', 'abs', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position. While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up,…', 90, false),
  ('db-barbell-ab-rollout-on-knees', 'Barbell Ab Rollout - On Knees', 'Barbell_Ab_Rollout_-_On_Knees', 'abs', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor. Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body.…', 90, false),
  ('db-barbell-curls-lying-against-an-incline', 'Barbell Curls Lying Against An Incline', 'Barbell_Curls_Lying_Against_An_Incline', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position. While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms. After a second contraction, slowly go back to the…', 60, false),
  ('db-barbell-full-squat', 'Barbell Full Squat', 'Barbell_Full_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time…', 90, false),
  ('db-barbell-guillotine-bench-press', 'Barbell Guillotine Bench Press', 'Barbell_Guillotine_Bench_Press', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, bring the bar down slowly until it is about 1 inch from your neck. After a second pause, bring the bar back to the starting position as…', 90, false),
  ('db-barbell-hack-squat', 'Barbell Hack Squat', 'Barbell_Hack_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position. While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go…', 90, false),
  ('db-barbell-incline-shoulder-raise', 'Barbell Incline Shoulder Raise', 'Barbell_Incline_Shoulder_Raise', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position. While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out. Bring back the bar to the starting position as…', 90, false),
  ('db-barbell-lunge', 'Barbell Lunge', 'Barbell_Lunge', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time…', 90, false),
  ('db-barbell-rear-delt-row', 'Barbell Rear Delt Row', 'Barbell_Rear_Delt_Row', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip. Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now…', 90, false),
  ('db-barbell-rollout-from-bench', 'Barbell Rollout from Bench', 'Barbell_Rollout_from_Bench', 'abs', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position. To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement. When the bar has been moved as far…', 90, false),
  ('db-barbell-seated-calf-raise', 'Barbell Seated Calf Raise', 'Barbell_Seated_Calf_Raise', 'calves', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Place a block about 12 inches in front of a flat bench. Sit on the bench and place the ball of your feet on the block. Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position. Raise up on your toes as high as possible as you squeeze the calves and as you breathe out. After a second contraction, slowly go back to the starting…', 60, false),
  ('db-barbell-shoulder-press', 'Barbell Shoulder Press', 'Barbell_Shoulder_Press', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward). Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the shoulders…', 90, false),
  ('db-barbell-shrug-behind-the-back', 'Barbell Shrug Behind The Back', 'Barbell_Shrug_Behind_The_Back', 'traps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position. Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second.…', 60, false),
  ('db-barbell-side-bend', 'Barbell Side Bend', 'Barbell_Side_Bend', 'abs', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position. While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip:…', 60, false),
  ('db-barbell-side-split-squat', 'Barbell Side Split Squat', 'Barbell_Side_Split_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position. Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your…', 90, false),
  ('db-barbell-squat-to-a-bench', 'Barbell Squat To A Bench', 'Barbell_Squat_To_A_Bench', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth. Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.…', 90, false),
  ('db-barbell-step-ups', 'Barbell Step Ups', 'Barbell_Step_Ups', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position. Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up…', 90, false),
  ('db-barbell-walking-lunge', 'Barbell Walking Lunge', 'Barbell_Walking_Lunge', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Begin standing with your feet shoulder width apart and a barbell across your upper back. Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up. Step forward with your rear…', 90, false),
  ('db-bench-jump', 'Bench Jump', 'Bench_Jump', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position. Perform a short squat in preparation for the jump; swing your arms behind you. Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up. Jump over the bench, landing with the knees bent, absorbing the…', 75, false),
  ('db-bench-press-powerlifting', 'Bench Press - Powerlifting', 'Bench_Press_-_Powerlifting', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring…', 150, false),
  ('db-bench-press-with-bands', 'Bench Press - With Bands', 'Bench_Press_-_With_Bands', 'chest', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Using a flat bench secure a band under the leg of the bench that is nearest to your head. Once the band is secure, grab it by both handles and lie down on the bench. Extend your arms so that you are holding the band handles in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down…', 90, false),
  ('db-bench-press-with-chains', 'Bench Press with Chains', 'Bench_Press_with_Chains', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar. Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this…', 150, false),
  ('db-bench-sprint', 'Bench Sprint', 'Bench_Sprint', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand on the ground with one foot resting on a bench or box with your heel close to the edge. Push off with your foot on top of the bench, extending through the hip and knee. Land with the opposite foot on top of the box, returning your other foot back to the start position. Continue alternating from one foot to another to complete the set.', 75, false),
  ('db-bent-over-dumbbell-rear-delt-raise-with-head-on-bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you. While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This…', 60, false),
  ('db-bent-over-low-pulley-side-lateral', 'Bent Over Low-Pulley Side Lateral', 'Bent_Over_Low-Pulley_Side_Lateral', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Select a weight and hold the handle of the low pulley with your right hand. Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position. Raise your right arm, elbow slightly bent,…', 60, false),
  ('db-bent-over-one-arm-long-bar-row', 'Bent Over One-Arm Long Bar Row', 'Bent_Over_One-Arm_Long_Bar_Row', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with one arm just behind the plates on the side where the weight was…', 90, true),
  ('db-bent-over-two-arm-long-bar-row', 'Bent Over Two-Arm Long Bar Row', 'Bent_Over_Two-Arm_Long_Bar_Row', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with both arms just behind the plates on the side where the weight…', 90, false),
  ('db-bent-over-two-dumbbell-row-with-palms-in', 'Bent Over Two-Dumbbell Row With Palms In', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'back', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the…', 90, false),
  ('db-bent-press', 'Bent Press', 'Bent_Press', 'abs', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position. Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so,…', 90, false),
  ('db-bent-arm-barbell-pullover', 'Bent-Arm Barbell Pullover', 'Bent-Arm_Barbell_Pullover', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Lie on a flat bench with a barbell using a shoulder grip width. Hold the bar straight over your chest with a bend in your arms. This will be your starting position. While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest. At that point, bring the barbell back to the starting position using the arc through which…', 90, false),
  ('db-bent-arm-dumbbell-pullover', 'Bent-Arm Dumbbell Pullover', 'Bent-Arm_Dumbbell_Pullover', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over…', 90, false),
  ('db-bent-knee-hip-raise', 'Bent-Knee Hip Raise', 'Bent-Knee_Hip_Raise', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lay flat on the floor with your arms next to your sides. Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches. Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the…', 90, false),
  ('db-bicycling', 'Bicycling', 'Bicycling', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'To begin, seat yourself on the bike and adjust the seat to your height.', 0, false),
  ('db-board-press', 'Board Press', 'Board_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet…', 150, false),
  ('db-body-tricep-press', 'Body Tricep Press', 'Body_Tricep_Press', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Position a bar in a rack at chest height. Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position. Begin by flexing the elbow, lowering yourself towards the bar. Pause, and then reverse the motion by extending the elbows. Progress from bodyweight by adding chains over your shoulders.', 60, false),
  ('db-body-up', 'Body-Up', 'Body-Up', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position. Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. Slowly lower your forearms back to the…', 60, false),
  ('db-bodyweight-flyes', 'Bodyweight Flyes', 'Bodyweight_Flyes', 'chest', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll. Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight. Place your hands on the bars. This will be your starting position. Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale…', 60, false),
  ('db-bodyweight-mid-row', 'Bodyweight Mid Row', 'Bodyweight_Mid_Row', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position. Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up…', 90, false),
  ('db-bosu-ball-cable-crunch-with-side-bends', 'Bosu Ball Cable Crunch With Side Bends', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Connect a standard handle to each arm of a cable machine, and position them in the most downward position. Grab a Bosu Ball and position it in front and center of the cable machine. Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it. With both hands, reach back and grab the handle of each cable. With your feet positioned in…', 60, false),
  ('db-bottoms-up', 'Bottoms Up', 'Bottoms_Up', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position. To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor. After a brief pause,…', 90, false),
  ('db-bottoms-up-clean-from-the-hang-position', 'Bottoms-Up Clean From The Hang Position', 'Bottoms-Up_Clean_From_The_Hang_Position', 'forearms', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-forearms-compound', 'Initiate the exercise by standing upright with a kettlebell in one hand. Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.', 90, false),
  ('db-box-jump-multiple-response', 'Box Jump (Multiple Response)', 'Box_Jump_Multiple_Response', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent. Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform. Immediately drop or jump back down to the original starting place; then repeat the sequence.', 75, false),
  ('db-box-skip', 'Box Skip', 'Box_Skip', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'You will need several boxes lined up about 8 feet apart. Begin facing the first box with one leg slightly behind the other. Drive off the back leg, attempting to gain as much height with the hips as possible. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.…', 75, false),
  ('db-box-squat', 'Box Squat', 'Box_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades…', 150, false),
  ('db-box-squat-with-bands', 'Box Squat with Bands', 'Box_Squat_with_Bands', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more…', 150, false),
  ('db-box-squat-with-chains', 'Box Squat with Chains', 'Box_Squat_with_Chains', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at…', 90, false),
  ('db-bradford-rocky-presses', 'Bradford/Rocky Presses', 'Bradford_Rocky_Presses', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position. Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms. Now lower the bar…', 90, false),
  ('db-butt-lift-bridge', 'Butt Lift (Bridge)', 'Butt_Lift_Bridge', 'glutes', 'bodyweight', 'time', array['time']::text[], 'isolation', 'db-glutes-isolation', 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position. Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second. Slowly go back to the starting position as you breathe in.', 60, false),
  ('db-butt-ups', 'Butt-Ups', 'Butt-Ups', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle. Arch your back slightly out rather than keeping your back completely straight. Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you…', 90, false),
  ('db-cable-chest-press', 'Cable Chest Press', 'Cable_Chest_Press', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After…', 90, false),
  ('db-cable-deadlifts', 'Cable Deadlifts', 'Cable_Deadlifts', 'quads', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. To begin, squat down be flexing your hips and knees until you can reach the handles. After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement. After reaching a full…', 90, false),
  ('db-cable-incline-pushdown', 'Cable Incline Pushdown', 'Cable_Incline_Pushdown', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position. Keeping the upper arms stationary, lift your arms back in a semi circle…', 60, false),
  ('db-cable-incline-triceps-extension', 'Cable Incline Triceps Extension', 'Cable_Incline_Triceps_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor. Keeping the upper arms stationary, extend the arms as you…', 60, false),
  ('db-cable-internal-rotation', 'Cable Internal Rotation', 'Cable_Internal_Rotation', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'rotation', 'Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead. Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position. Pull the single hand…', 90, false),
  ('db-cable-iron-cross', 'Cable Iron Cross', 'Cable_Iron_Cross', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position. Keeping the elbows extended, pull your arms straight to your sides. Return your arms back to the starting position after a…', 60, false),
  ('db-cable-judo-flip', 'Cable Judo Flip', 'Cable_Judo_Flip', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands. Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip. Shift your weight between your feet as you twist and crunch forward, pulling the cable downward. Return to the starting…', 90, false),
  ('db-cable-lying-triceps-extension', 'Cable Lying Triceps Extension', 'Cable_Lying_Triceps_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down. With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position. Lower the bar by bending at the elbow while keeping the upper arms…', 60, false),
  ('db-cable-one-arm-tricep-extension', 'Cable One Arm Tricep Extension', 'Cable_One_Arm_Tricep_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack. Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you…', 60, true),
  ('db-cable-preacher-curl', 'Cable Preacher Curl', 'Cable_Preacher_Curl', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Place a preacher bench about 2 feet in front of a pulley machine. Attach a straight bar to the low pulley. Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position. Now start pilling the weight up towards your shoulders…', 60, false),
  ('db-cable-reverse-crunch', 'Cable Reverse Crunch', 'Cable_Reverse_Crunch', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it. Sit down with your feet toward the pulley and attach the cable to your ankles. Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are. With your hands behind your head, bring your knees inward to your…', 60, false),
  ('db-cable-rope-rear-delt-rows', 'Cable Rope Rear-Delt Rows', 'Cable_Rope_Rear-Delt_Rows', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out. Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position. Pull the cable…', 90, false),
  ('db-cable-russian-twists', 'Cable Russian Twists', 'Cable_Russian_Twists', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'rotation', 'Connect a standard handle attachment, and position the cable to a middle pulley position. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley.…', 90, false),
  ('db-cable-seated-crunch', 'Cable Seated Crunch', 'Cable_Seated_Crunch', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Seat on a flat bench with your back facing a high pulley. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position. With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this…', 60, false),
  ('db-cable-shoulder-press', 'Cable Shoulder Press', 'Cable_Shoulder_Press', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press the handles directly over head. After pausing at the top, return to the starting position and repeat.', 90, false),
  ('db-cable-wrist-curl', 'Cable Wrist Curl', 'Cable_Wrist_Curl', 'forearms', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment. Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees. Start out by curling your wrist upwards and exhaling. Keep the contraction for a…', 60, false),
  ('db-calf-press', 'Calf Press', 'Calf_Press', 'calves', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform. Select an appropriate weight, and grasp the handles. This will be your starting position. Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward…', 60, false),
  ('db-calf-raise-on-a-dumbbell', 'Calf Raise On A Dumbbell', 'Calf_Raise_On_A_Dumbbell', 'calves', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position. Lift the calf as you roll your foot over the top of the…', 60, false),
  ('db-calf-raises-with-bands', 'Calf Raises - With Bands', 'Calf_Raises_-_With_Bands', 'calves', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This…', 60, false),
  ('db-calf-machine-shoulder-shrug', 'Calf-Machine Shoulder Shrug', 'Calf-Machine_Shoulder_Shrug', 'traps', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position. Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second. Slowly return to the starting position as you inhale. Repeat for the recommended amount of repetitions.', 60, false),
  ('db-car-deadlift', 'Car Deadlift', 'Car_Deadlift', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs. Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to…', 90, false),
  ('db-car-drivers', 'Car Drivers', 'Car_Drivers', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position. Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. Reverse the motion,…', 60, false),
  ('db-carioca-quick-step', 'Carioca Quick Step', 'Carioca_Quick_Step', 'adductors', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position. With your right foot, quick step behind and pull the knee up. Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.', 75, false),
  ('db-catch-and-overhead-throw', 'Catch and Overhead Throw', 'Catch_and_Overhead_Throw', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin standing while facing a wall or a partner. Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than…', 75, false),
  ('db-chain-handle-extension', 'Chain Handle Extension', 'Chain_Handle_Extension', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up. Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated. Pause at the lockout, and reverse the motion to return to the starting position.', 150, false),
  ('db-chain-press', 'Chain Press', 'Chain_Press', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position. Lower the chains by flexing the elbows, unloading some of the chain onto the floor. Continue until your elbow forms a 90 degree angle, and then reverse the motion by…', 150, false),
  ('db-chair-squat', 'Chair Squat', 'Chair_Squat', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look…', 90, false),
  ('db-chest-push-multiple-response', 'Chest Push (multiple response)', 'Chest_Push_multiple_response', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. Follow through by falling forward, catching yourself with your hands. Immediately return to an upright position. Repeat for the desired number of repetitions.', 75, false),
  ('db-chest-push-single-response', 'Chest Push (single response)', 'Chest_Push_single_response', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin in a kneeling position holding the medicine ball with both hands tightly into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. Follow through by falling forward, catching yourself with your hands.', 75, false),
  ('db-chest-push-from-3-point-stance', 'Chest Push from 3 point stance', 'Chest_Push_from_3_point_stance', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you. To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw. As you execute the second step, explosively release the ball forward as hard as possible.', 75, false),
  ('db-chest-push-with-run-release', 'Chest Push with Run Release', 'Chest_Push_with_Run_Release', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position. While taking your first step draw the medicine ball into your chest. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!', 75, false),
  ('db-circus-bell', 'Circus Bell', 'Circus_Bell', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands. Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand. Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip…', 90, false),
  ('db-clean', 'Clean', 'Clean', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms…', 150, false),
  ('db-clean-and-press', 'Clean and Press', 'Clean_and_Press', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be…', 90, false),
  ('db-clean-deadlift', 'Clean Deadlift', 'Clean_Deadlift', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible. Begin by driving through the floor…', 150, false),
  ('db-clean-from-blocks', 'Clean from Blocks', 'Clean_from_Blocks', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your…', 150, false),
  ('db-clean-pull', 'Clean Pull', 'Clean_Pull', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should…', 150, false),
  ('db-clean-shrug', 'Clean Shrug', 'Clean_Shrug', 'traps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.', 150, false),
  ('db-clock-push-up', 'Clock Push-Up', 'Clock_Push-Up', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest toward the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as…', 90, false),
  ('db-close-grip-dumbbell-press', 'Close-Grip Dumbbell Press', 'Close-Grip_Dumbbell_Press', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor. Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the…', 90, false),
  ('db-close-grip-ez-bar-curl', 'Close-Grip EZ Bar Curl', 'Close-Grip_EZ_Bar_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only…', 60, false),
  ('db-close-grip-ez-bar-curl-with-band', 'Close-Grip EZ-Bar Curl with Band', 'Close-Grip_EZ-Bar_Curl_with_Band', 'biceps', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position. While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted. Continue the movement until your biceps are fully contracted and the bar is…', 60, false),
  ('db-close-grip-ez-bar-press', 'Close-Grip EZ-Bar Press', 'Close-Grip_EZ-Bar_Press', 'triceps', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lie on a flat bench with an EZ bar loaded to an appropriate weight. Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement. Using the triceps to push the bar back up, press it back to…', 90, false),
  ('db-close-grip-push-up-off-of-a-dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'Close-Grip_Push-Up_off_of_a_Dumbbell', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position. Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag. Press yourself back up to the starting position by extending the elbows.…', 90, false),
  ('db-close-grip-standing-barbell-curl', 'Close-Grip Standing Barbell Curl', 'Close-Grip_Standing_Barbell_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Hold a barbell with both hands, palms up and a few inches apart. Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this…', 60, false),
  ('db-cocoons', 'Cocoons', 'Cocoons', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position. To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion. After a brief pause, return to the…', 90, false),
  ('db-conans-wheel', 'Conan''s Wheel', 'Conans_Wheel', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms. Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you…', 90, false),
  ('db-cross-body-hammer-curl', 'Cross Body Hammer Curl', 'Cross_Body_Hammer_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in. While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second. Slowly lower the dumbbell along the same path as you inhale and then…', 60, false),
  ('db-cross-over-with-bands', 'Cross Over - With Bands', 'Cross_Over_-_With_Bands', 'chest', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Secure an exercise band around a stationary post. While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will…', 90, false),
  ('db-cross-body-crunch', 'Cross-Body Crunch', 'Cross-Body_Crunch', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie flat on your back and bend your knees about 60 degrees. Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position. Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try…', 90, false),
  ('db-crucifix', 'Crucifix', 'Crucifix', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'complex', 'In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different. Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know…', 60, false),
  ('db-crunch-hands-overhead', 'Crunch - Hands Overhead', 'Crunch_-_Hands_Overhead', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves. Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position. Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them…', 60, false),
  ('db-crunch-legs-on-exercise-ball', 'Crunch - Legs On Exercise Ball', 'Crunch_-_Legs_On_Exercise_Ball', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle. Place your feet three to four inches apart and point your toes inward so they touch. Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. Push the small of your back down in the floor in order to better isolate your abdominal muscles.…', 60, false),
  ('db-cuban-press', 'Cuban Press', 'Cuban_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position. To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly…', 90, false),
  ('db-deadlift-with-bands', 'Deadlift with Bands', 'Deadlift_with_Bands', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and…', 150, false),
  ('db-deadlift-with-chains', 'Deadlift with Chains', 'Deadlift_with_Chains', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.…', 150, false),
  ('db-decline-close-grip-bench-to-skull-crusher', 'Decline Close-Grip Bench To Skull Crusher', 'Decline_Close-Grip_Bench_To_Skull_Crusher', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help…', 90, false),
  ('db-decline-dumbbell-bench-press', 'Decline Dumbbell Bench Press', 'Decline_Dumbbell_Bench_Press', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the weights…', 90, false),
  ('db-decline-dumbbell-flyes', 'Decline Dumbbell Flyes', 'Decline_Dumbbell_Flyes', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. With a slight…', 90, false),
  ('db-decline-dumbbell-triceps-extension', 'Decline Dumbbell Triceps Extension', 'Decline_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. As you breathe…', 60, false),
  ('db-decline-ez-bar-triceps-extension', 'Decline EZ Bar Triceps Extension', 'Decline_EZ_Bar_Triceps_Extension', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help…', 60, false),
  ('db-decline-oblique-crunch', 'Decline Oblique Crunch', 'Decline_Oblique_Crunch', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor. Put one hand beside your head and the other on your thigh. This will be your starting position. Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale…', 90, false),
  ('db-decline-reverse-crunch', 'Decline Reverse Crunch', 'Decline_Reverse_Crunch', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position. Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position. While exhaling, move your legs towards the torso as…', 90, false),
  ('db-decline-smith-press', 'Decline Smith Press', 'Decline_Smith_Press', 'chest', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position. As you inhale, lower the bar under control by allowing the elbows to flex,…', 90, false),
  ('db-deficit-deadlift', 'Deficit Deadlift', 'Deficit_Deadlift', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big…', 150, false),
  ('db-depth-jump-leap', 'Depth Jump Leap', 'Depth_Jump_Leap', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high. Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer. Begin by dropping off the initial box, landing and simultaneously taking off with both…', 75, false),
  ('db-donkey-calf-raises', 'Donkey Calf Raises', 'Donkey_Calf_Raises', 'calves', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad. Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to…', 60, false),
  ('db-double-kettlebell-alternating-hang-clean', 'Double Kettlebell Alternating Hang Clean', 'Double_Kettlebell_Alternating_Hang_Clean', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell. With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.', 90, false),
  ('db-double-kettlebell-jerk', 'Double Kettlebell Jerk', 'Double_Kettlebell_Jerk', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Hold a kettlebell by the handle in each hand. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence…', 90, false),
  ('db-double-kettlebell-push-press', 'Double Kettlebell Push Press', 'Double_Kettlebell_Push_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean two kettlebells to your shoulders. Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead. Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.', 90, false),
  ('db-double-kettlebell-snatch', 'Double Kettlebell Snatch', 'Double_Kettlebell_Snatch', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells. Swing the kettlebells between your legs forcefully and reverse the direction. Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 90, false),
  ('db-double-kettlebell-windmill', 'Double Kettlebell Windmill', 'Double_Kettlebell_Windmill', 'abs', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'rotation', 'Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out…', 90, false),
  ('db-double-leg-butt-kick', 'Double Leg Butt Kick', 'Double_Leg_Butt_Kick', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin standing with your knees slightly bent. Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height. As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks. Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.', 75, false),
  ('db-downward-facing-balance', 'Downward Facing Balance', 'Downward_Facing_Balance', 'glutes', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-glutes-isolation', 'Lie facedown on top of an exercise ball. While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.', 60, false),
  ('db-drag-curl', 'Drag Curl', 'Drag_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-biceps-compound', 'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position. As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not…', 90, false),
  ('db-drop-push', 'Drop Push', 'Drop_Push', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Position low boxes or other platforms 2-3 feet apart. Move to a pushup position between them, supporting yourself by placing your hands on the boxes. With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.', 75, false),
  ('db-dumbbell-alternate-bicep-curl', 'Dumbbell Alternate Bicep Curl', 'Dumbbell_Alternate_Bicep_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs. While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the…', 60, false),
  ('db-dumbbell-bench-press-with-neutral-grip', 'Dumbbell Bench Press with Neutral Grip', 'Dumbbell_Bench_Press_with_Neutral_Grip', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted. Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position. Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to…', 90, false),
  ('db-dumbbell-floor-press', 'Dumbbell Floor Press', 'Dumbbell_Floor_Press', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you. Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side. Pause at the bottom, and then bring the weight together at the top by extending through the elbows.', 150, false),
  ('db-dumbbell-incline-shoulder-raise', 'Dumbbell Incline Shoulder Raise', 'Dumbbell_Incline_Shoulder_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs. Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position. While keeping the arms straight…', 60, false),
  ('db-dumbbell-lying-one-arm-rear-lateral-raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability. Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your…', 60, true),
  ('db-dumbbell-lying-pronation', 'Dumbbell Lying Pronation', 'Dumbbell_Lying_Pronation', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm…', 60, false),
  ('db-dumbbell-lying-rear-lateral-raise', 'Dumbbell Lying Rear Lateral Raise', 'Dumbbell_Lying_Rear_Lateral_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms…', 60, false),
  ('db-dumbbell-lying-supination', 'Dumbbell Lying Supination', 'Dumbbell_Lying_Supination', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front…', 60, false),
  ('db-dumbbell-one-arm-shoulder-press', 'Dumbbell One-Arm Shoulder Press', 'Dumbbell_One-Arm_Shoulder_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. Rotate the wrist so that the palm of your hand is facing forward. This is your…', 90, true),
  ('db-dumbbell-one-arm-triceps-extension', 'Dumbbell One-Arm Triceps Extension', 'Dumbbell_One-Arm_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept…', 60, true),
  ('db-dumbbell-one-arm-upright-row', 'Dumbbell One-Arm Upright Row', 'Dumbbell_One-Arm_Upright_Row', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs. Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.…', 90, true),
  ('db-dumbbell-prone-incline-curl', 'Dumbbell Prone Incline Curl', 'Dumbbell_Prone_Incline_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way). Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor. Now keep your elbows in by your side and face the palms forward. This will be your starting position. Raise…', 60, false),
  ('db-dumbbell-raise', 'Dumbbell Raise', 'Dumbbell_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to…', 90, false),
  ('db-dumbbell-scaption', 'Dumbbell Scaption', 'Dumbbell_Scaption', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up. Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement. Continue until your arms are parallel to the ground, and then return to the starting position.', 60, false),
  ('db-dumbbell-seated-one-leg-calf-raise', 'Dumbbell Seated One-Leg Calf Raise', 'Dumbbell_Seated_One-Leg_Calf_Raise', 'calves', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Place a block on the floor about 12 inches from a flat bench. Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee. Now place the ball of your left foot on the block. This will be your starting position. Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second. Slowly return to the starting position,…', 60, true),
  ('db-dumbbell-side-bend', 'Dumbbell Side Bend', 'Dumbbell_Side_Bend', 'abs', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position. While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting…', 60, false),
  ('db-dumbbell-squat', 'Dumbbell Squat', 'Dumbbell_Squat', 'quads', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs). Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described…', 90, false),
  ('db-dumbbell-squat-to-a-bench', 'Dumbbell Squat To A Bench', 'Dumbbell_Squat_To_A_Bench', 'quads', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs). Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the…', 90, false),
  ('db-dumbbell-tricep-extension-pronated-grip', 'Dumbbell Tricep Extension -Pronated Grip', 'Dumbbell_Tricep_Extension_-Pronated_Grip', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor. The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position. Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and…', 60, false),
  ('db-elbow-to-knee', 'Elbow to Knee', 'Elbow_to_Knee', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position. Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee. Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.', 90, false),
  ('db-elevated-back-lunge', 'Elevated Back Lunge', 'Elevated_Back_Lunge', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you. Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position. Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor. Pause, and extend…', 90, false),
  ('db-elevated-cable-rows', 'Elevated Cable Rows', 'Elevated_Cable_Rows', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height. Place it on the seat of the cable row machine. Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended…', 90, false),
  ('db-exercise-ball-crunch', 'Exercise Ball Crunch', 'Exercise_Ball_Crunch', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head…', 60, false),
  ('db-exercise-ball-pull-in', 'Exercise Ball Pull-In', 'Exercise_Ball_Pull-In', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position. Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be…', 90, false),
  ('db-extended-range-one-arm-kettlebell-floor-press', 'Extended Range One-Arm Kettlebell Floor Press', 'Extended_Range_One-Arm_Kettlebell_Floor_Press', 'chest', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body. Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.', 90, true),
  ('db-external-rotation', 'External Rotation', 'External_Rotation', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso. Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel…', 60, false),
  ('db-external-rotation-with-band', 'External Rotation with Band', 'External_Rotation_with_Band', 'shoulders', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'rotation', 'Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away. Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees…', 90, false),
  ('db-external-rotation-with-cable', 'External Rotation with Cable', 'External_Rotation_with_Cable', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away. Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of…', 60, false),
  ('db-fast-skipping', 'Fast Skipping', 'Fast_Skipping', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Start in a relaxed position with one leg slightly forward. This will be your starting position. Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth. Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.', 75, false),
  ('db-finger-curls', 'Finger Curls', 'Finger_Curls', 'forearms', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position. Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers. Now curl bar up as high as possible…', 60, false),
  ('db-flat-bench-cable-flyes', 'Flat Bench Cable Flyes', 'Flat_Bench_Cable_Flyes', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys. Lay flat on the bench and keep your feet on the ground. Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip. Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through…', 60, false),
  ('db-flat-bench-leg-pull-in', 'Flat Bench Leg Pull-In', 'Flat_Bench_Leg_Pull-In', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie on an exercise mat or a flat bench with your legs off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your…', 90, false),
  ('db-flexor-incline-dumbbell-curls', 'Flexor Incline Dumbbell Curls', 'Flexor_Incline_Dumbbell_Curls', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them. Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand. Let…', 60, false),
  ('db-floor-glute-ham-raise', 'Floor Glute-Ham Raise', 'Floor_Glute-Ham_Raise', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-hamstrings-isolation', 'You can use a partner for this exercise or brace your feet under something stable. Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position. Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward. Place your hands in front of you as you reach the floor. This…', 60, false),
  ('db-floor-press', 'Floor Press', 'Floor_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower…', 150, false),
  ('db-floor-press-with-chains', 'Floor Press with Chains', 'Floor_Press_with_Chains', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the…', 150, false),
  ('db-forward-drag-with-press', 'Forward Drag with Press', 'Forward_Drag_with_Press', 'chest', 'other', 'custom', array['weight','distance']::text[], 'compound', 'complex', 'Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand. Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.', 90, false),
  ('db-frankenstein-squat', 'Frankenstein Squat', 'Frankenstein_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'This drill teaches you the proper positioning of both the bar and your body during the clean and front squat. Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic…', 150, false),
  ('db-frog-sit-ups', 'Frog Sit-Ups', 'Frog_Sit-Ups', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you. Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other. Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create…', 60, false),
  ('db-front-barbell-squat-to-a-bench', 'Front Barbell Squat To A Bench', 'Front_Barbell_Squat_To_A_Bench', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while…', 90, false),
  ('db-front-cone-hops-or-hurdle-hops', 'Front Cone Hops (or hurdle hops)', 'Front_Cone_Hops_or_hurdle_hops', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Set up a row of cones or other small barriers, placing them a few feet apart. Stand in front of the first cone with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first cone, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone. Continue until you have jumped…', 75, false),
  ('db-front-dumbbell-raise', 'Front Dumbbell Raise', 'Front_Dumbbell_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly…', 60, false),
  ('db-front-plate-raise', 'Front Plate Raise', 'Front_Plate_Raise', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position. Slowly raise the…', 60, false),
  ('db-front-raise-and-pullover', 'Front Raise And Pullover', 'Front_Raise_And_Pullover', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart. Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position. Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your…', 90, false),
  ('db-front-squat-clean-grip', 'Front Squat (Clean Grip)', 'Front_Squat_Clean_Grip', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position. Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position…', 90, false),
  ('db-front-two-dumbbell-raise', 'Front Two-Dumbbell Raise', 'Front_Two-Dumbbell_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above…', 60, false),
  ('db-full-range-of-motion-lat-pulldown', 'Full Range-Of-Motion Lat Pulldown', 'Full_Range-Of-Motion_Lat_Pulldown', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward. Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate…', 90, false),
  ('db-gironda-sternum-chins', 'Gironda Sternum Chins', 'Gironda_Sternum_Chins', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Grasp the pull-up bar with a shoulder width underhand grip. Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position. Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this…', 90, false),
  ('db-glute-ham-raise', 'Glute Ham Raise', 'Glute_Ham_Raise', 'hamstrings', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad. Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright. Return to…', 150, false),
  ('db-good-morning-off-pins', 'Good Morning off Pins', 'Good_Morning_off_Pins', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical…', 150, false),
  ('db-gorilla-chin-crunch', 'Gorilla Chin/Crunch', 'Gorilla_Chin_Crunch', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width. Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position. As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going…', 90, false),
  ('db-hammer-grip-incline-db-bench-press', 'Hammer Grip Incline DB Bench Press', 'Hammer_Grip_Incline_DB_Bench_Press', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms…', 90, false),
  ('db-hang-clean-below-the-knees', 'Hang Clean - Below the Knees', 'Hang_Clean_-_Below_the_Knees', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward. Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the…', 150, false),
  ('db-hang-snatch', 'Hang Snatch', 'Hang_Snatch', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug the…', 150, false),
  ('db-hang-snatch-below-knees', 'Hang Snatch - Below Knees', 'Hang_Snatch_-_Below_Knees', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug…', 150, false),
  ('db-hanging-bar-good-morning', 'Hanging Bar Good Morning', 'Hanging_Bar_Good_Morning', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly…', 150, false),
  ('db-hanging-pike', 'Hanging Pike', 'Hanging_Pike', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar. Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your…', 90, false),
  ('db-heaving-snatch-balance', 'Heaving Snatch Balance', 'Heaving_Snatch_Balance', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with. Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full…', 150, false),
  ('db-heavy-bag-thrust', 'Heavy Bag Thrust', 'Heavy_Bag_Thrust', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position. Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body. Receive the bag as it swings back by reversing these steps.', 75, false),
  ('db-high-cable-curls', 'High Cable Curls', 'High_Cable_Curls', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-biceps-compound', 'Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position. Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move.…', 90, false),
  ('db-hip-extension-with-bands', 'Hip Extension with Bands', 'Hip_Extension_with_Bands', 'glutes', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-glutes-compound', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Facing the attachment point of the band, hold on to the column to stabilize yourself. Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight. Return the leg to the starting position.', 90, false),
  ('db-hip-flexion-with-band', 'Hip Flexion with Band', 'Hip_Flexion_with_Band', 'quads', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Face away from the attachment point of the band. Keeping your head and your chest up, raise your knee up to 90 degrees and pause. Return the leg to the starting position.', 90, false),
  ('db-hip-lift-with-band', 'Hip Lift with Band', 'Hip_Lift_with_Band', 'glutes', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-glutes-compound', 'After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move. Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in…', 150, false),
  ('db-hyperextensions-with-no-hyperextension-bench', 'Hyperextensions With No Hyperextension Bench', 'Hyperextensions_With_No_Hyperextension_Bench', 'lower_back', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench. With your body…', 90, false),
  ('db-incline-barbell-triceps-extension', 'Incline Barbell Triceps Extension', 'Incline_Barbell_Triceps_Extension', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width. Lie back on an incline bench set at any angle between 45-75-degrees. Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position. Now lower the bar in a semicircular motion behind your head until your forearms touch…', 60, false),
  ('db-incline-bench-pull', 'Incline Bench Pull', 'Incline_Bench_Pull', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees. Let the arms hang to your sides fully extended as they point to the floor. Turn the wrists until your hands have a pronated (palms down) grip. Now flare the elbows out. This will be your starting position. As you breathe out, start to pull the dumbbells up as if you are doing a reverse…', 60, false),
  ('db-incline-cable-chest-press', 'Incline Cable Chest Press', 'Incline_Cable_Chest_Press', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After…', 90, false),
  ('db-incline-cable-flye', 'Incline Cable Flye', 'Incline_Cable_Flye', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso). Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand. With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your…', 60, false),
  ('db-incline-dumbbell-bench-with-palms-facing-in', 'Incline Dumbbell Bench With Palms Facing In', 'Incline_Dumbbell_Bench_With_Palms_Facing_In', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms…', 90, false),
  ('db-incline-dumbbell-flyes-with-a-twist', 'Incline Dumbbell Flyes - With A Twist', 'Incline_Dumbbell_Flyes_-_With_A_Twist', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'rotation', 'Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping…', 90, false),
  ('db-incline-hammer-curls', 'Incline Hammer Curls', 'Incline_Hammer_Curls', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position. Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary. Continue to the top of the movement and pause, then slowly return…', 60, false),
  ('db-incline-inner-biceps-curl', 'Incline Inner Biceps Curl', 'Incline_Inner_Biceps_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Hold a dumbbell in each hand and lie back on an incline bench. The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position. Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The…', 60, false),
  ('db-incline-push-up-close-grip', 'Incline Push-Up Close-Grip', 'Incline_Push-Up_Close-Grip', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands next to one another on the bar. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.', 90, false),
  ('db-incline-push-up-depth-jump', 'Incline Push-Up Depth Jump', 'Incline_Push-Up_Depth_Jump', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps. Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position. Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As…', 75, false),
  ('db-incline-push-up-medium', 'Incline Push-Up Medium', 'Incline_Push-Up_Medium', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself…', 90, false),
  ('db-incline-push-up-reverse-grip', 'Incline Push-Up Reverse Grip', 'Incline_Push-Up_Reverse_Grip', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar palms up, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing…', 90, false),
  ('db-incline-push-up-wide', 'Incline Push-Up Wide', 'Incline_Push-Up_Wide', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands wider than shoulder width. Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting…', 90, false),
  ('db-internal-rotation-with-band', 'Internal Rotation with Band', 'Internal_Rotation_with_Band', 'shoulders', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away. Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees…', 60, false),
  ('db-inverted-row-with-straps', 'Inverted Row with Straps', 'Inverted_Row_with_Straps', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position. Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement. Pause at the top…', 90, false),
  ('db-iron-cross', 'Iron Cross', 'Iron_Cross', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', '', 90, false),
  ('db-isometric-chest-squeezes', 'Isometric Chest Squeezes', 'Isometric_Chest_Squeezes', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso). Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.…', 75, false),
  ('db-isometric-neck-exercise-front-and-back', 'Isometric Neck Exercise - Front And Back', 'Isometric_Neck_Exercise_-_Front_And_Back', 'traps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head. Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the…', 60, false),
  ('db-isometric-neck-exercise-sides', 'Isometric Neck Exercise - Sides', 'Isometric_Neck_Exercise_-_Sides', 'traps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head. Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now…', 60, false),
  ('db-isometric-wipers', 'Isometric Wipers', 'Isometric_Wipers', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position. Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body. Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to…', 90, false),
  ('db-janda-sit-up', 'Janda Sit-Up', 'Janda_Sit-Up', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position. As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings…', 60, false),
  ('db-jefferson-squats', 'Jefferson Squats', 'Jefferson_Squats', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Place a barbell on the floor. Stand in the middle of the bar length wise. Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side. Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip…', 90, false),
  ('db-jerk-balance', 'Jerk Balance', 'Jerk_Balance', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart. Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not…', 150, false),
  ('db-jerk-dip-squat', 'Jerk Dip Squat', 'Jerk_Dip_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable. Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip…', 150, false),
  ('db-jm-press', 'JM Press', 'JM_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position. Now beginning from a fully extended position lower the bar down as if…', 90, false),
  ('db-jogging-treadmill', 'Jogging, Treadmill', 'Jogging_Treadmill', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than…', 0, false),
  ('db-keg-load', 'Keg Load', 'Keg_Load', 'lower_back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet. Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest. The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on…', 90, false),
  ('db-kettlebell-arnold-press', 'Kettlebell Arnold Press', 'Kettlebell_Arnold_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward. Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion. Return the kettlebell to the starting position, with the palm facing in.', 90, false),
  ('db-kettlebell-halo-with-overhead-extension', 'Kettlebell Halo with Overhead Extension', null, 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position. Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here. From this position, extend your…', 90, false),
  ('db-kettlebell-hang-clean', 'Kettlebell Hang Clean', 'Kettlebell_Hang_Clean', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead. Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep…', 90, false),
  ('db-kettlebell-overhead-triceps-extension', 'Kettlebell Overhead Triceps Extension', null, 'triceps', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands. Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position. Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows…', 60, false),
  ('db-kettlebell-pirate-ships', 'Kettlebell Pirate Ships', 'Kettlebell_Pirate_Ships', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position. Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion. Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height. Repeat for the desired amount of…', 90, false),
  ('db-kettlebell-seated-press', 'Kettlebell Seated Press', 'Kettlebell_Seated_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit on the floor and spread your legs out comfortably. Clean one kettlebell to your shoulder. Press the kettlebell up and out until it is locked out overhead. Return to the starting position.', 90, false),
  ('db-kettlebell-seesaw-press', 'Kettlebell Seesaw Press', 'Kettlebell_Seesaw_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean two kettlebells two your shoulders. Press one kettlebell. Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.', 90, false),
  ('db-kettlebell-turkish-get-up-squat-style', 'Kettlebell Turkish Get-Up (Squat style)', 'Kettlebell_Turkish_Get-Up_Squat_style', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell. Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at…', 90, false),
  ('db-kipping-muscle-up', 'Kipping Muscle Up', 'Kipping_Muscle_Up', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Grip the rings using a false grip, with the base of your palms on top of the rings. Begin with a movement swinging your legs backward slightly. Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your…', 90, false),
  ('db-knee-hip-raise-on-parallel-bars', 'Knee/Hip Raise On Parallel Bars', 'Knee_Hip_Raise_On_Parallel_Bars', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle. The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position. Now as you breathe out, lift your legs up as you…', 60, false),
  ('db-kneeling-arm-drill', 'Kneeling Arm Drill', 'Kneeling_Arm_Drill', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated. Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint. As soon as your hands pass the hip, accelerate…', 75, false),
  ('db-kneeling-cable-crunch-with-alternating-oblique-twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it. Grab the rope with both hands and kneel approximately two feet back from the tower. Position the rope behind your head with your hands by your ears. Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees. Pause briefly at the bottom…', 60, false),
  ('db-kneeling-cable-triceps-extension', 'Kneeling Cable Triceps Extension', 'Kneeling_Cable_Triceps_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Place a bench sideways in front of a high pulley machine. Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down. Face away from the machine and kneel. Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position. While keeping your upper arms…', 60, false),
  ('db-kneeling-high-pulley-row', 'Kneeling High Pulley Row', 'Kneeling_High_Pulley_Row', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position. Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out. After pausing briefly, slowly return to the…', 90, false),
  ('db-kneeling-jump-squat', 'Kneeling Jump Squat', 'Kneeling_Jump_Squat', 'glutes', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier. Sit back with your hips until your glutes touch your feet, keeping your head and chest up. Explode up with your hips, generating enough power to land with your feet flat on the floor. Continue with the squat by…', 150, false),
  ('db-kneeling-single-arm-high-pulley-row', 'Kneeling Single-Arm High Pulley Row', 'Kneeling_Single-Arm_High_Pulley_Row', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Attach a single handle to a high pulley and make your weight selection. Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position. Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is…', 90, true),
  ('db-kneeling-squat', 'Kneeling Squat', 'Kneeling_Squat', 'glutes', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-glutes-compound', 'Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight. With your head looking forward, sit back with your butt until you touch your calves. Reverse the motion, returning the…', 150, false),
  ('db-lateral-cone-hops', 'Lateral Cone Hops', 'Lateral_Cone_Hops', 'adductors', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Position a number of cones in a row several feet apart. Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position. Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. Use your legs to absorb impact upon landing, and rebound into the next…', 75, false),
  ('db-lateral-raise-with-bands', 'Lateral Raise - With Bands', 'Lateral_Raise_-_With_Bands', 'shoulders', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the…', 60, false),
  ('db-leg-lift', 'Leg Lift', 'Leg_Lift', 'glutes', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-glutes-isolation', 'While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance. With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement. Slowly bring the raised leg back…', 60, false),
  ('db-leg-pull-in', 'Leg Pull-In', 'Leg_Pull-In', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a…', 90, false),
  ('db-leg-over-floor-press', 'Leg-Over Floor Press', 'Leg-Over_Floor_Press', 'chest', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support. Press the kettlebll into a locked out position. Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.', 90, false),
  ('db-leverage-chest-press', 'Leverage Chest Press', 'Leverage_Chest_Press', 'chest', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start…', 90, false),
  ('db-leverage-deadlift', 'Leverage Deadlift', 'Leverage_Deadlift', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position. Return the weight to the starting position.', 90, false),
  ('db-leverage-decline-chest-press', 'Leverage Decline Chest Press', 'Leverage_Decline_Chest_Press', 'chest', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position,…', 90, false),
  ('db-leverage-high-row', 'Leverage High Row', 'Leverage_High_Row', 'back', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting…', 90, false),
  ('db-leverage-shoulder-press', 'Leverage Shoulder Press', 'Leverage_Shoulder_Press', 'shoulders', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position. Press the handles upward by extending through the elbow. After a brief pause at the top, return the weight to just above the start position,…', 90, false),
  ('db-leverage-shrug', 'Leverage Shrug', 'Leverage_Shrug', 'traps', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your…', 60, false),
  ('db-linear-3-part-start-technique', 'Linear 3-Part Start Technique', 'Linear_3-Part_Start_Technique', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left. Place your right hand onto the line, and thing bring your nose close to your left knee. Squat down as you lean foward, your head being lower than…', 75, false),
  ('db-linear-acceleration-wall-drill', 'Linear Acceleration Wall Drill', 'Linear_Acceleration_Wall_Drill', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted. Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground. Switch legs, raising the opposite knee, and then attacking the ground straight down. Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right…', 75, false),
  ('db-log-lift', 'Log Lift', 'Log_Lift', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean. Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the…', 90, false),
  ('db-london-bridges', 'London Bridges', 'London_Bridges', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized. Stand on the bar, using the rope to balance yourself. This will be your starting position. Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until…', 90, false),
  ('db-low-cable-triceps-extension', 'Low Cable Triceps Extension', 'Low_Cable_Triceps_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment. Grab the outside of the rope ends with your palms facing each other (neutral grip). Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and…', 60, false),
  ('db-low-pulley-row-to-neck', 'Low Pulley Row To Neck', 'Low_Pulley_Row_To_Neck', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit on a low pulley row machine with a rope attachment. Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position. While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck…', 90, false),
  ('db-lunge-pass-through', 'Lunge Pass Through', 'Lunge_Pass_Through', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position. Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground. As you lunge, pass the kettlebell under your front leg to your opposite hand. Pressing through the heel of your foot, return to…', 90, false),
  ('db-lunge-sprint', 'Lunge Sprint', 'Lunge_Sprint', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position. Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so. At the bottom of the descent, immediately reverse…', 90, false),
  ('db-lying-cable-curl', 'Lying Cable Curl', 'Lying_Cable_Curl', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip. Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight. With your arms extended and your elbows close to your body slightly bend your arms. This will be your…', 60, false),
  ('db-lying-cambered-barbell-row', 'Lying Cambered Barbell Row', 'Lying_Cambered_Barbell_Row', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Place a cambered bar underneath an exercise bench. Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position. As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. After a second…', 60, false),
  ('db-lying-close-grip-bar-curl-on-high-pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Place a flat bench in front of a high pulley or lat pulldown machine. Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width. Lie on your back with your head over the end of the bench. Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position. As you breathe…', 60, false),
  ('db-lying-close-grip-barbell-triceps-extension-behind-the-head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms…', 60, false),
  ('db-lying-close-grip-barbell-triceps-press-to-chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'triceps', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso…', 60, false),
  ('db-lying-face-down-plate-neck-resistance', 'Lying Face Down Plate Neck Resistance', 'Lying_Face_Down_Plate_Neck_Resistance', 'traps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position. While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes")…', 60, false),
  ('db-lying-face-up-plate-neck-resistance', 'Lying Face Up Plate Neck Resistance', 'Lying_Face_Up_Plate_Neck_Resistance', 'traps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position. While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion…', 60, false),
  ('db-lying-high-bench-barbell-curl', 'Lying High Bench Barbell Curl', 'Lying_High_Bench_Barbell_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular…', 60, false),
  ('db-lying-machine-squat', 'Lying Machine Squat', 'Lying_Machine_Squat', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel. Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly…', 90, false),
  ('db-lying-one-arm-lateral-raise', 'Lying One-Arm Lateral Raise', 'Lying_One-Arm_Lateral_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability. Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your…', 60, true),
  ('db-lying-rear-delt-raise', 'Lying Rear Delt Raise', 'Lying_Rear_Delt_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'While holding a dumbbell in each hand, lay with your chest down on a flat bench. Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms…', 60, false),
  ('db-lying-supine-dumbbell-curl', 'Lying Supine Dumbbell Curl', 'Lying_Supine_Dumbbell_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs. Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip). While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go…', 60, false),
  ('db-lying-t-bar-row', 'Lying T-Bar Row', 'Lying_T-Bar_Row', 'back', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part…', 90, false),
  ('db-lying-triceps-press', 'Lying Triceps Press', 'Lying_Triceps_Press', 'triceps', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor. Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position. As you breathe in, slowly…', 60, false),
  ('db-machine-bicep-curl', 'Machine Bicep Curl', 'Machine_Bicep_Curl', 'biceps', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm. Pause at the top of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until…', 60, false),
  ('db-middle-back-shrug', 'Middle Back Shrug', 'Middle_Back_Shrug', 'back', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position. As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to…', 60, false),
  ('db-mixed-grip-chin', 'Mixed Grip Chin', 'Mixed_Grip_Chin', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position. Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should…', 90, false),
  ('db-monster-walk', 'Monster Walk', 'Monster_Walk', 'abductors', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abductors-compound', 'Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart. To begin, take short steps forward alternating your left and right foot. After several steps, do just the opposite and walk backward to where you started.', 90, false),
  ('db-moving-claw-series', 'Moving Claw Series', 'Moving_Claw_Series', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends. Reload the quad as the leg moves back forward, attacking the ground on the next step. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.', 75, false),
  ('db-muscle-snatch', 'Muscle Snatch', 'Muscle_Snatch', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by…', 150, false),
  ('db-narrow-stance-hack-squats', 'Narrow Stance Hack Squats', 'Narrow_Stance_Hack_Squats', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles…', 90, false),
  ('db-narrow-stance-leg-press', 'Narrow Stance Leg Press', 'Narrow_Stance_Leg_Press', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Lower the safety bars holding the weighted platform in place and press the platform…', 90, false),
  ('db-narrow-stance-squats', 'Narrow Stance Squats', 'Narrow_Stance_Squats', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same…', 90, false),
  ('db-natural-glute-ham-raise', 'Natural Glute Ham Raise', 'Natural_Glute_Ham_Raise', 'hamstrings', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture. This will be your starting position. Lower yourself under control until your knees are almost completely straight. Remaining in control, raise yourself back up to the starting…', 90, false),
  ('db-neck-press', 'Neck Press', 'Neck_Press', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your neck. After a second pause, bring the bar back to the starting…', 90, false),
  ('db-oblique-crunches', 'Oblique Crunches', 'Oblique_Crunches', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor. Make sure your feet are elevated and resting on a flat surface. Now lift the shoulder in which your hand is touching your head. Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right…', 60, false),
  ('db-oblique-crunches-on-the-floor', 'Oblique Crunches - On The Floor', 'Oblique_Crunches_-_On_The_Floor', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit. Place your left hand behind your head. Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques. Crunch as high as you can, hold the contraction for a second and then slowly drop back…', 60, false),
  ('db-olympic-squat', 'Olympic Squat', 'Olympic_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed. Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the…', 150, false),
  ('db-one-arm-chin-up', 'One Arm Chin-Up', 'One_Arm_Chin-Up', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'For this exercise, start out by placing a towel around a chin up bar. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v Pull your torso up until the bar touches your upper chest by…', 90, true),
  ('db-one-arm-dumbbell-bench-press', 'One Arm Dumbbell Bench Press', 'One_Arm_Dumbbell_Bench_Press', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie down on a flat bench with a dumbbell in one hand on top of your thigh. By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly. Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be…', 90, true),
  ('db-one-arm-dumbbell-preacher-curl', 'One Arm Dumbbell Preacher Curl', 'One_Arm_Dumbbell_Preacher_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell…', 60, true),
  ('db-one-arm-floor-press', 'One Arm Floor Press', 'One_Arm_Floor_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso). Make sure the hand you are not using to lift the weight is…', 90, true),
  ('db-one-arm-pronated-dumbbell-triceps-extension', 'One Arm Pronated Dumbbell Triceps Extension', 'One_Arm_Pronated_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to…', 60, true),
  ('db-one-arm-supinated-dumbbell-triceps-extension', 'One Arm Supinated Dumbbell Triceps Extension', 'One_Arm_Supinated_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember…', 60, true),
  ('db-one-leg-barbell-squat', 'One Leg Barbell Squat', 'One_Leg_Barbell_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other. Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest. Then lift the barbell over your head and rest…', 90, false),
  ('db-one-arm-flat-bench-dumbbell-flye', 'One-Arm Flat Bench Dumbbell Flye', 'One-Arm_Flat_Bench_Dumbbell_Flye', 'chest', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip. By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side…', 60, true),
  ('db-one-arm-high-pulley-cable-side-bends', 'One-Arm High-Pulley Cable Side Bends', 'One-Arm_High-Pulley_Cable_Side_Bends', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Connect a standard handle to a tower. Move cable to highest pulley position. Stand with side to cable. With one hand, reach up and grab handle with underhand grip. Pull down cable until elbow touches your side and the handle is by your shoulder. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. Keep arm in static position. Contract oblique to bring the weight down in a side crunch.…', 60, true),
  ('db-one-arm-incline-lateral-raise', 'One-Arm Incline Lateral Raise', 'One-Arm_Incline_Lateral_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel. Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position. While keeping the dumbbell parallel to the floor at all times, perform a…', 60, true),
  ('db-one-arm-kettlebell-jerk', 'One-Arm Kettlebell Jerk', 'One-Arm_Kettlebell_Jerk', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create…', 90, true),
  ('db-one-arm-kettlebell-para-press', 'One-Arm Kettlebell Para Press', 'One-Arm_Kettlebell_Para_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder…', 90, true),
  ('db-one-arm-kettlebell-split-jerk', 'One-Arm Kettlebell Split Jerk', 'One-Arm_Kettlebell_Split_Jerk', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create…', 90, true),
  ('db-one-arm-kettlebell-split-snatch', 'One-Arm Kettlebell Split Snatch', 'One-Arm_Kettlebell_Split_Snatch', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Hold a kettlebell in one hand by the handle. Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead. After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.…', 90, true),
  ('db-one-arm-long-bar-row', 'One-Arm Long Bar Row', 'One-Arm_Long_Bar_Row', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position. Pull the weight to your side by retracting…', 90, true),
  ('db-one-arm-medicine-ball-slam', 'One-Arm Medicine Ball Slam', 'One-Arm_Medicine_Ball_Slam', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position. Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam. At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground…', 90, true),
  ('db-one-arm-open-palm-kettlebell-clean', 'One-Arm Open Palm Kettlebell Clean', 'One-Arm_Open_Palm_Kettlebell_Clean', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Place one kettlebell between your feet. Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand. Throw the kettlebell out in front of you and catch the handle with one hand. Take the kettlebell to the floor and repeat. Make sure to work both arms.', 90, true),
  ('db-one-arm-overhead-kettlebell-squats', 'One-Arm Overhead Kettlebell Squats', 'One-Arm_Overhead_Kettlebell_Squats', 'quads', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position. Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso…', 90, true),
  ('db-one-arm-side-deadlift', 'One-Arm Side Deadlift', 'One-Arm_Side_Deadlift', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell. Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position. Use your legs to help lift the barbell up while exhaling. Your arms should extend…', 90, true),
  ('db-one-arm-side-laterals', 'One-Arm Side Laterals', 'One-Arm_Side_Laterals', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance. Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your…', 60, true),
  ('db-open-palm-kettlebell-clean', 'Open Palm Kettlebell Clean', 'Open_Palm_Kettlebell_Clean', 'hamstrings', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders. Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands. Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.', 90, false),
  ('db-otis-up', 'Otis-Up', 'Otis-Up', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position. Initiate the movement by flexing the hips and spine to raise your torso up from the ground. As you move up, press the weight up so that it is above your head at the top of the movement. Return the weight to your chest as you reverse the sit-up motion, ensuring…', 90, false),
  ('db-overhead-cable-curl', 'Overhead Cable Curl', 'Overhead_Cable_Curl', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders. Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your…', 60, false),
  ('db-overhead-squat', 'Overhead Squat', 'Overhead_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other. Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest. Move the barbell over and slightly…', 150, false),
  ('db-palms-down-dumbbell-wrist-curl-over-a-bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower…', 60, false),
  ('db-palms-up-dumbbell-wrist-curl-over-a-bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your…', 60, false),
  ('db-parallel-bar-dip', 'Parallel Bar Dip', 'Parallel_Bar_Dip', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out. Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position. Repeat for…', 90, false),
  ('db-physioball-hip-bridge', 'Physioball Hip Bridge', 'Physioball_Hip_Bridge', 'glutes', 'other', 'time', array['time']::text[], 'compound', 'db-glutes-compound', 'Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position. Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge. Pause at the top of the motion and return to the starting position.', 90, false),
  ('db-pin-presses', 'Pin Presses', 'Pin_Presses', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion. The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting. Begin by lying on the bench, with the bar…', 150, false),
  ('db-plate-pinch', 'Plate Pinch', 'Plate_Pinch', 'forearms', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Grab two wide-rimmed plates and put them together with the smooth sides facing outward Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. Repeat for the recommended amount of sets prescribed in your program. Switch arms…', 60, false),
  ('db-platform-hamstring-slides', 'Platform Hamstring Slides', 'Platform_Hamstring_Slides', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-hamstrings-isolation', 'For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position. Begin the movement by flexing the knee, keeping your other leg straight. Continue bringing the heel closer to you, sliding it on the floor. At full knee flexion, reverse the movement to return to the starting position.', 60, false),
  ('db-plie-dumbbell-squat', 'Plie Dumbbell Squat', 'Plie_Dumbbell_Squat', 'quads', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent. Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position. Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale…', 90, false),
  ('db-plyo-kettlebell-pushups', 'Plyo Kettlebell Pushups', 'Plyo_Kettlebell_Pushups', 'chest', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position. Begin by lowering yourself as low as you can, keeping your back straight. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so.…', 90, false),
  ('db-power-clean-from-blocks', 'Power Clean from Blocks', 'Power_Clean_from_Blocks', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As…', 150, false),
  ('db-power-jerk', 'Power Jerk', 'Power_Jerk', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the…', 150, false),
  ('db-power-partials', 'Power Partials', 'Power_Partials', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position. Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.…', 60, false),
  ('db-power-snatch', 'Power Snatch', 'Power_Snatch', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the first pull by driving through the front…', 150, false),
  ('db-power-snatch-from-blocks', 'Power Snatch from Blocks', 'Power_Snatch_from_Blocks', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position. Begin the first pull by driving through the…', 150, false),
  ('db-power-stairs', 'Power Stairs', 'Power_Stairs', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box. Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground. As you lean back, attempt to swing the weight onto the stairs, which are usually around…', 90, false),
  ('db-preacher-hammer-dumbbell-curl', 'Preacher Hammer Dumbbell Curl', 'Preacher_Hammer_Dumbbell_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip). As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps…', 60, false),
  ('db-press-sit-up', 'Press Sit-Up', 'Press_Sit-Up', 'abs', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position. While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform…', 90, false),
  ('db-prone-manual-hamstring', 'Prone Manual Hamstring', 'Prone_Manual_Hamstring', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-hamstrings-isolation', 'You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel. To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels. Pause at the top, returning the leg to the starting…', 60, false),
  ('db-prowler-sprint', 'Prowler Sprint', 'Prowler_Sprint', 'hamstrings', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down. You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement. With good posture, drive through the ground with alternating, short steps. Move…', 0, false),
  ('db-push-press-behind-the-neck', 'Push Press - Behind the Neck', 'Push_Press_-_Behind_the_Neck', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path. Using the momentum generated, finish pressing the weight overhead be…', 150, false),
  ('db-push-up-wide', 'Push-Up Wide', 'Push-Up_Wide', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position. To begin, allow the elbows to flex, lowering your chest to the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as…', 90, false),
  ('db-push-ups-close-triceps-position', 'Push-Ups - Close Triceps Position', 'Push-Ups_-_Close_Triceps_Position', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length. Lower yourself until your chest almost touches the floor as you inhale. Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a…', 90, false),
  ('db-push-ups-with-feet-elevated', 'Push-Ups With Feet Elevated', 'Push-Ups_With_Feet_Elevated', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your…', 90, false),
  ('db-push-ups-with-feet-on-an-exercise-ball', 'Push-Ups With Feet On An Exercise Ball', 'Push-Ups_With_Feet_On_An_Exercise_Ball', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of an exercise ball. This will allow your body to be elevated. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform…', 90, false),
  ('db-pushups-close-and-wide-hand-positions', 'Pushups (Close and Wide Hand Positions)', 'Pushups_Close_and_Wide_Hand_Positions', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and…', 90, false),
  ('db-quick-leap', 'Quick Leap', 'Quick_Leap', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'You will need a box for this exerise. Begin facing the box standing 1-2 feet from its edge. By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat. Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.', 75, false),
  ('db-rack-delivery', 'Rack Delivery', 'Rack_Delivery', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs. Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should…', 150, false),
  ('db-rack-pull-with-bands', 'Rack Pull with Bands', 'Rack_Pull_with_Bands', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips,…', 150, false),
  ('db-rack-pulls', 'Rack Pulls', 'Rack_Pulls', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip,…', 150, false),
  ('db-recumbent-bike', 'Recumbent Bike', 'Recumbent_Bike', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'To begin, seat yourself on the bike and adjust the seat to your height. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be…', 0, false),
  ('db-return-push-from-stance', 'Return Push from Stance', 'Return_Push_from_Stance', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'You will need a partner for this drill. Begin in an athletic 2 or 3 point stance. At the signal, move into a position to receive the pass from your partner. Catch the medicine ball with both hands and immediately throw it back to your partner. You can modify this drill by running different routes.', 75, false),
  ('db-reverse-band-bench-press', 'Reverse Band Bench Press', 'Reverse_Band_Bench_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell. Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them,…', 150, false),
  ('db-reverse-band-box-squat', 'Reverse Band Box Squat', 'Reverse_Band_Box_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the…', 150, false),
  ('db-reverse-band-deadlift', 'Reverse Band Deadlift', 'Reverse_Band_Deadlift', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip…', 150, false),
  ('db-reverse-band-power-squat', 'Reverse Band Power Squat', 'Reverse_Band_Power_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your…', 150, false),
  ('db-reverse-band-sumo-deadlift', 'Reverse Band Sumo Deadlift', 'Reverse_Band_Sumo_Deadlift', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a…', 150, false),
  ('db-reverse-barbell-preacher-curls', 'Reverse Barbell Preacher Curls', 'Reverse_Barbell_Preacher_Curls', 'biceps', 'ez_bar', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab an EZ-bar using a shoulder width and palms down (pronated) grip. Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position. As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position. As you breathe in,…', 60, false),
  ('db-reverse-cable-curl', 'Reverse Cable Curl', 'Reverse_Cable_Curl', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until…', 60, false),
  ('db-reverse-flyes', 'Reverse Flyes', 'Reverse_Flyes', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip). Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position. Maintaining the slight bend of the…', 60, false),
  ('db-reverse-flyes-with-external-rotation', 'Reverse Flyes With External Rotation', 'Reverse_Flyes_With_External_Rotation', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes…', 60, false),
  ('db-reverse-grip-bent-over-rows', 'Reverse Grip Bent-Over Rows', 'Reverse_Grip_Bent-Over_Rows', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Stand erect while holding a barbell with a supinated grip (palms facing up). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.…', 90, false),
  ('db-reverse-grip-triceps-pushdown', 'Reverse Grip Triceps Pushdown', 'Reverse_Grip_Triceps_Pushdown', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Start by setting a bar attachment (straight or e-z) on a high pulley machine. Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position. Slowly elevate the bar…', 60, false),
  ('db-reverse-plate-curls', 'Reverse Plate Curls', 'Reverse_Plate_Curls', 'biceps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position. Your feet should be shoulder width apart from each other and the weighted plate should be…', 60, false),
  ('db-reverse-triceps-bench-press', 'Reverse Triceps Bench Press', 'Reverse_Triceps_Bench_Press', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows…', 90, false),
  ('db-rickshaw-carry', 'Rickshaw Carry', 'Rickshaw_Carry', 'forearms', 'other', 'custom', array['weight','distance']::text[], 'compound', 'complex', 'Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight. Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to…', 90, false),
  ('db-rickshaw-deadlift', 'Rickshaw Deadlift', 'Rickshaw_Deadlift', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'complex', 'Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract. With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the…', 90, false),
  ('db-ring-dips', 'Ring Dips', 'Ring_Dips', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out. Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position. Repeat for the desired number of repetitions.', 90, false),
  ('db-rocket-jump', 'Rocket Jump', 'Rocket_Jump', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.', 75, false),
  ('db-rocking-standing-calf-raise', 'Rocking Standing Calf Raise', 'Rocking_Standing_Calf_Raise', 'calves', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time…', 60, false),
  ('db-rocky-pull-ups-pulldowns', 'Rocky Pull-Ups/Pulldowns', 'Rocky_Pull-Ups_Pulldowns', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms…', 90, false),
  ('db-romanian-deadlift-from-deficit', 'Romanian Deadlift from Deficit', 'Romanian_Deadlift_from_Deficit', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion. Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done…', 150, false),
  ('db-rope-crunch', 'Rope Crunch', 'Rope_Crunch', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Kneel 1-2 feet in front of a cable system with a rope attached. After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position. To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down. Pause at the bottom of the motion, and then slowly return to the starting position. These can be done…', 60, false),
  ('db-rope-straight-arm-pulldown', 'Rope Straight-Arm Pulldown', 'Rope_Straight-Arm_Pulldown', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-back-isolation', 'Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position. Keeping your arms straight, extend the shoulder to pull the rope down to your thighs. Pause at the bottom of the…', 60, false),
  ('db-scapular-pull-up', 'Scapular Pull-Up', 'Scapular_Pull-Up', 'traps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Take a pronated grip on a pull-up bar. From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion. Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.', 60, false),
  ('db-scissors-jump', 'Scissors Jump', 'Scissors_Jump', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground. Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front. As you land,…', 75, false),
  ('db-seated-band-hamstring-curl', 'Seated Band Hamstring Curl', 'Seated_Band_Hamstring_Curl', 'hamstrings', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-hamstrings-isolation', 'Secure a band close to the ground and place a bench a couple feet away from it. Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position. Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor. Pause at the completion of the movement, and then slowly return…', 60, false),
  ('db-seated-barbell-military-press', 'Seated Barbell Military Press', 'Seated_Barbell_Military_Press', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. Once you pick up the barbell with the correct…', 90, false),
  ('db-seated-bent-over-one-arm-dumbbell-triceps-extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is…', 60, true),
  ('db-seated-bent-over-two-arm-dumbbell-triceps-extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they…', 60, false),
  ('db-seated-cable-shoulder-press', 'Seated Cable Shoulder Press', 'Seated_Cable_Shoulder_Press', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together above your head. After pausing at the top, return the handles to the starting position. Ensure…', 90, false),
  ('db-seated-close-grip-concentration-barbell-curl', 'Seated Close-Grip Concentration Barbell Curl', 'Seated_Close-Grip_Concentration_Barbell_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor. Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip:…', 60, false),
  ('db-seated-dumbbell-curl', 'Seated Dumbbell Curl', 'Seated_Dumbbell_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing your torso. This will be your starting position. While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement.…', 60, false),
  ('db-seated-dumbbell-inner-biceps-curl', 'Seated Dumbbell Inner Biceps Curl', 'Seated_Dumbbell_Inner_Biceps_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids.…', 60, false),
  ('db-seated-dumbbell-palms-down-wrist-curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your…', 60, false),
  ('db-seated-dumbbell-palms-up-wrist-curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'Seated_Dumbbell_Palms-Up_Wrist_Curl', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.…', 60, false),
  ('db-seated-dumbbell-press', 'Seated Dumbbell Press', 'Seated_Dumbbell_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs. Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. This is your starting position. As you exhale, push the…', 90, false),
  ('db-seated-flat-bench-leg-pull-in', 'Seated Flat Bench Leg Pull-In', 'Seated_Flat_Bench_Leg_Pull-In', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the…', 90, false),
  ('db-seated-good-mornings', 'Seated Good Mornings', 'Seated_Good_Mornings', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With…', 150, false),
  ('db-seated-head-harness-neck-resistance', 'Seated Head Harness Neck Resistance', 'Seated_Head_Harness_Neck_Resistance', 'traps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out. Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on…', 60, false),
  ('db-seated-leg-tucks', 'Seated Leg Tucks', 'Seated_Leg_Tucks', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the…', 60, false),
  ('db-seated-one-arm-cable-pulley-rows', 'Seated One-arm Cable Pulley Rows', 'Seated_One-arm_Cable_Pulley_Rows', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip. With your arm extended pull back until your torso is at a 90-degree angle from your…', 90, true),
  ('db-seated-one-arm-dumbbell-palms-down-wrist-curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight…', 60, true),
  ('db-seated-one-arm-dumbbell-palms-up-wrist-curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'forearms', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight…', 60, true),
  ('db-seated-palm-up-barbell-wrist-curl', 'Seated Palm-Up Barbell Wrist Curl', 'Seated_Palm-Up_Barbell_Wrist_Curl', 'forearms', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible…', 60, false),
  ('db-seated-palms-down-barbell-wrist-curl', 'Seated Palms-Down Barbell Wrist Curl', 'Seated_Palms-Down_Barbell_Wrist_Curl', 'forearms', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as…', 60, false),
  ('db-seated-triceps-press', 'Seated Triceps Press', 'Seated_Triceps_Press', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position. Keeping your upper arms close to your head…', 60, false),
  ('db-seated-two-arm-palms-up-low-pulley-wrist-curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'forearms', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it. Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up. Now hold the handle with both hands, palms up, using a shoulder-width grip. Step back and sit on the bench with your feet about shoulder width apart, firmly on…', 60, false),
  ('db-see-saw-press-alternating-side-press', 'See-Saw Press (Alternating Side Press)', 'See-Saw_Press_Alternating_Side_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Grab a dumbbell with each hand and stand up erect. Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position. Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should…', 90, false),
  ('db-shotgun-row', 'Shotgun Row', 'Shotgun_Row', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Attach a single handle to a low cable. After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position. Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go. After a brief pause, return to the starting position.', 90, false),
  ('db-shoulder-press-with-bands', 'Shoulder Press - With Bands', 'Shoulder_Press_-_With_Bands', 'shoulders', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position. As you exhale, lift the handles up until your arms are fully…', 90, false),
  ('db-side-hop-sprint', 'Side Hop-Sprint', 'Side_Hop-Sprint', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand to the side of a cone or hurdle. Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started. Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.', 75, false),
  ('db-side-jackknife', 'Side Jackknife', 'Side_Jackknife', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', '', 90, false),
  ('db-side-laterals-to-front-raise', 'Side Laterals to Front Raise', 'Side_Laterals_to_Front_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'In a standing position, hold a pair of dumbbells at your side. This will be your starting position. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. At the top of the exercise move the weights out in front of you, keeping your arms extended. Lower the weights with a controlled motion. On the next repetition, raise the weights in…', 60, false),
  ('db-side-standing-long-jump', 'Side Standing Long Jump', 'Side_Standing_Long_Jump', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position. Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can. Land facing the same direction with your feet hip width apart, absorbing…', 75, false),
  ('db-side-to-side-box-shuffle', 'Side to Side Box Shuffle', 'Side_to_Side_Box_Shuffle', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand to one side of the box with your left foot resting on the middle of it. To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement. Continue shuffling back and forth across the box.', 75, false),
  ('db-side-to-side-chins', 'Side To Side Chins', 'Side_To_Side_Chins', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing…', 90, false),
  ('db-single-dumbbell-raise', 'Single Dumbbell Raise', 'Single_Dumbbell_Raise', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position. Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement. Return to the starting position and repeat for the recommended…', 60, false),
  ('db-single-leg-butt-kick', 'Single Leg Butt Kick', 'Single_Leg_Butt_Kick', 'quads', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Begin by standing on one leg, with the bent knee raised. This will be your start position. Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg. Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg. Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same…', 75, true),
  ('db-single-leg-push-off', 'Single Leg Push-off', 'Single_Leg_Push-off', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand on the ground with one foot resting on the box, heel close to the edge. Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee. Land with the same foot on top of the box, returning your other foot back to the start position.', 75, true),
  ('db-single-arm-cable-crossover', 'Single-Arm Cable Crossover', 'Single-Arm_Cable_Crossover', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-chest-isolation', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position. Keeping your left arm in place, allow your right arm to extend…', 60, true),
  ('db-single-arm-linear-jammer', 'Single-Arm Linear Jammer', 'Single-Arm_Linear_Jammer', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position. Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force. Return to the starting…', 90, true),
  ('db-single-arm-push-up', 'Single-Arm Push-Up', 'Single-Arm_Push-Up', 'chest', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up. Maintain good posture, and place your free hand behind your back. This will be your…', 90, true),
  ('db-single-cone-sprint-drill', 'Single-Cone Sprint Drill', 'Single-Cone_Sprint_Drill', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward. Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action. Rest after three trips around the cone.', 75, false),
  ('db-single-leg-high-box-squat', 'Single-Leg High Box Squat', 'Single-Leg_High_Box_Squat', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Position a box in a rack. Secure a band or rope in place above the box. Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance . Continue stepping up and down on the same leg before switching to the opposite side.', 90, true),
  ('db-single-leg-lateral-hop', 'Single-Leg Lateral Hop', 'Single-Leg_Lateral_Hop', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent. To begin, execute a counterjump to hop sideways over the cone. Land on your jumping leg, and immediately rebound out of it by jumping back to the start position. Continue hopping back and forth.', 75, true),
  ('db-single-leg-leg-extension', 'Single-Leg Leg Extension', 'Single-Leg_Leg_Extension', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-quads-isolation', 'Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities. Maintaining good posture, fully extend one leg, pausing at the top of the motion. Return to the starting position without letting the…', 60, true),
  ('db-single-leg-stride-jump', 'Single-Leg Stride Jump', 'Single-Leg_Stride_Jump', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the same position that you started, using your inside leg to decelerate the impact.', 75, true),
  ('db-sit-up', 'Sit-Up', 'Sit-Up', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees. Place your hands behind your head and lock them together by clasping your fingers. This is the starting position. Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise. Once you…', 60, false),
  ('db-skating', 'Skating', 'Skating', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury. You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval…', 0, false),
  ('db-sled-overhead-backward-walk', 'Sled Overhead Backward Walk', 'Sled_Overhead_Backward_Walk', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position. Walk backwards, keeping your arms raised above your head. Avoid jerky movements.', 90, false),
  ('db-sled-overhead-triceps-extension', 'Sled Overhead Triceps Extension', 'Sled_Overhead_Triceps_Extension', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load. Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position. Extend through the elbow to straighten the arm. Ensure that your upper…', 60, false),
  ('db-sled-reverse-flye', 'Sled Reverse Flye', 'Sled_Reverse_Flye', 'shoulders', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position. Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external…', 60, false),
  ('db-sled-row', 'Sled Row', 'Sled_Row', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line. With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended. To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you. Take a step or two back…', 90, false),
  ('db-smith-incline-shoulder-raise', 'Smith Incline Shoulder Raise', 'Smith_Incline_Shoulder_Raise', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell. Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a…', 60, false),
  ('db-smith-machine-behind-the-back-shrug', 'Smith Machine Behind the Back Shrug', 'Smith_Machine_Behind_the_Back_Shrug', 'traps', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-traps-isolation', 'With the bar at thigh level, load an appropriate weight. Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position. Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement. After a brief…', 60, false),
  ('db-smith-machine-bent-over-row', 'Smith Machine Bent Over Row', 'Smith_Machine_Bent_Over_Row', 'back', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Set the barbell attached to the smith machine to a height that is about 2 inches below your knees. Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang…', 90, false),
  ('db-smith-machine-close-grip-bench-press', 'Smith Machine Close-Grip Bench Press', 'Smith_Machine_Close-Grip_Bench_Press', 'triceps', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting…', 90, false),
  ('db-smith-machine-decline-press', 'Smith Machine Decline Press', 'Smith_Machine_Decline_Press', 'chest', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench. Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position. Begin the movement by flexing your arms, lowering the bar to your chest. Pause briefly, and then…', 90, false),
  ('db-smith-machine-hang-power-clean', 'Smith Machine Hang Power Clean', 'Smith_Machine_Hang_Power_Clean', 'hamstrings', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Position the bar at knee height and load it to an appropriate weight. Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position. Initate the…', 90, false),
  ('db-smith-machine-hip-raise', 'Smith Machine Hip Raise', 'Smith_Machine_Hip_Raise', 'abs', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position. Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of…', 60, false),
  ('db-smith-machine-leg-press', 'Smith Machine Leg Press', 'Smith_Machine_Leg_Press', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position. Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your…', 90, false),
  ('db-smith-machine-one-arm-upright-row', 'Smith Machine One-Arm Upright Row', 'Smith_Machine_One-Arm_Upright_Row', 'shoulders', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'With the bar at thigh level, load an appropriate weight. Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position. Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor. After…', 90, true),
  ('db-smith-machine-pistol-squat', 'Smith Machine Pistol Squat', 'Smith_Machine_Pistol_Squat', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3 Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain…', 90, false),
  ('db-smith-machine-reverse-calf-raises', 'Smith Machine Reverse Calf Raises', 'Smith_Machine_Reverse_Calf_Raises', 'calves', 'machine', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar. Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance. Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by…', 60, false),
  ('db-smith-machine-stiff-legged-deadlift', 'Smith Machine Stiff-Legged Deadlift', 'Smith_Machine_Stiff-Legged_Deadlift', 'hamstrings', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight…', 90, false),
  ('db-smith-machine-upright-row', 'Smith Machine Upright Row', 'Smith_Machine_Upright_Row', 'traps', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-traps-compound', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the…', 90, false),
  ('db-smith-single-leg-split-squat', 'Smith Single-Leg Split Squat', 'Smith_Single-Leg_Split_Squat', 'quads', 'machine', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs…', 90, true),
  ('db-snatch-balance', 'Snatch Balance', 'Snatch_Balance', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip. Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position. Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the…', 150, false),
  ('db-snatch-deadlift', 'Snatch Deadlift', 'Snatch_Deadlift', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward. Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar…', 150, false),
  ('db-snatch-from-blocks', 'Snatch from Blocks', 'Snatch_from_Blocks', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position. Begin the first pull by driving through the…', 150, false),
  ('db-snatch-pull', 'Snatch Pull', 'Snatch_Pull', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the…', 90, false),
  ('db-snatch-shrug', 'Snatch Shrug', 'Snatch_Shrug', 'traps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.', 150, false),
  ('db-speed-band-overhead-triceps', 'Speed Band Overhead Triceps', 'Speed_Band_Overhead_Triceps', 'triceps', 'band', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band. To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position. To perform the movement, extend through the elbow to to straighten your arms, ensuring that…', 60, false),
  ('db-speed-box-squat', 'Speed Box Squat', 'Speed_Box_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension. Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max. Position the bar on your upper back, shoulder blades retracted, back arched…', 150, false),
  ('db-speed-squats', 'Speed Squats', 'Speed_Squats', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same…', 90, false),
  ('db-spell-caster', 'Spell Caster', 'Spell_Caster', 'abs', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position. Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso. Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side. Continue alternating, rotating…', 90, false),
  ('db-spider-crawl', 'Spider Crawl', 'Spider_Crawl', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position. Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible. Return this leg to the starting position and repeat on…', 90, false),
  ('db-split-clean', 'Split Clean', 'Split_Clean', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain…', 150, false),
  ('db-split-jerk', 'Split Jerk', 'Split_Jerk', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the…', 150, false),
  ('db-split-snatch', 'Split Snatch', 'Split_Snatch', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the first pull by driving through the front…', 150, false),
  ('db-squat-jerk', 'Squat Jerk', 'Squat_Jerk', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the…', 90, false),
  ('db-squat-with-bands', 'Squat with Bands', 'Squat_with_Bands', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into…', 150, false),
  ('db-squat-with-chains', 'Squat with Chains', 'Squat_with_Chains', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend…', 150, false),
  ('db-squat-with-plate-movers', 'Squat with Plate Movers', 'Squat_with_Plate_Movers', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it. Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso. Step away from the rack and adopt a wide stance with…', 90, false),
  ('db-squats-with-bands', 'Squats - With Bands', 'Squats_-_With_Bands', 'quads', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other. When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have…', 90, false),
  ('db-standing-alternating-dumbbell-press', 'Standing Alternating Dumbbell Press', 'Standing_Alternating_Dumbbell_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position. Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement. After a brief pause, return the weight to the starting position. Repeat for the opposite side, continuing to…', 90, false),
  ('db-standing-barbell-calf-raise', 'Standing Barbell Calf Raise', 'Standing_Barbell_Calf_Raise', 'calves', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-calves-isolation', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same…', 60, false),
  ('db-standing-barbell-press-behind-neck', 'Standing Barbell Press Behind Neck', 'Standing_Barbell_Press_Behind_Neck', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at…', 90, false),
  ('db-standing-bent-over-one-arm-dumbbell-triceps-extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should…', 60, true),
  ('db-standing-bent-over-two-arm-dumbbell-triceps-extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There…', 60, false),
  ('db-standing-bradford-press', 'Standing Bradford Press', 'Standing_Bradford_Press', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position. Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head. Lower the bar down to the back of the head until your elbow forms a right angle. Lift the bar…', 90, false),
  ('db-standing-cable-chest-press', 'Standing Cable Chest Press', 'Standing_Cable_Chest_Press', 'chest', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability. Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position. Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing…', 90, false),
  ('db-standing-cable-lift', 'Standing Cable Lift', 'Standing_Cable_Lift', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Connect a standard handle on a tower, and move the cable to the lowest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, squat down and grab the…', 90, false),
  ('db-standing-concentration-curl', 'Standing Concentration Curl', 'Standing_Concentration_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position. Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause. Lower the dumbbell back to the starting position. Repeat the movement for the prescribed amount of repetitions.', 60, false),
  ('db-standing-dumbbell-press', 'Standing Dumbbell Press', 'Standing_Dumbbell_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position. Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head. Pause, and slowly return the weight to the starting position.', 90, false),
  ('db-standing-dumbbell-reverse-curl', 'Standing Dumbbell Reverse Curl', 'Standing_Dumbbell_Reverse_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully…', 60, false),
  ('db-standing-dumbbell-straight-arm-front-delt-raise-above-head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Hold the dumbbells in front of your thighs, palms facing your thighs. Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position. Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale. Slowly return to the starting position using the same path as you inhale. Repeat for the recommended amount of repetitions.', 60, false),
  ('db-standing-dumbbell-upright-row', 'Standing Dumbbell Upright Row', 'Standing_Dumbbell_Upright_Row', 'traps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-traps-compound', 'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it…', 90, false),
  ('db-standing-front-barbell-raise-over-head', 'Standing Front Barbell Raise Over Head', 'Standing_Front_Barbell_Raise_Over_Head', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other. Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position. Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when…', 60, false),
  ('db-standing-inner-biceps-curl', 'Standing Inner-Biceps Curl', 'Standing_Inner-Biceps_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your…', 60, false),
  ('db-standing-low-pulley-deltoid-raise', 'Standing Low-Pulley Deltoid Raise', 'Standing_Low-Pulley_Deltoid_Raise', 'shoulders', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance. Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting…', 60, false),
  ('db-standing-low-pulley-one-arm-triceps-extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'Standing_Low-Pulley_One-Arm_Triceps_Extension', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This…', 60, true),
  ('db-standing-olympic-plate-hand-squeeze', 'Standing Olympic Plate Hand Squeeze', 'Standing_Olympic_Plate_Hand_Squeeze', 'forearms', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position. Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates. Now raise the plates back to the starting position as you exhale by…', 60, false),
  ('db-standing-one-arm-cable-curl', 'Standing One-Arm Cable Curl', 'Standing_One-Arm_Cable_Curl', 'biceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight. Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance. Slowly begin to curl the single handle upwards while…', 60, true),
  ('db-standing-one-arm-dumbbell-curl-over-incline-bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip. Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the…', 60, true),
  ('db-standing-one-arm-dumbbell-triceps-extension', 'Standing One-Arm Dumbbell Triceps Extension', 'Standing_One-Arm_Dumbbell_Triceps_Extension', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head. This will be your starting position. Keeping your upper arm close to your head…', 60, true),
  ('db-standing-overhead-barbell-triceps-extension', 'Standing Overhead Barbell Triceps Extension', 'Standing_Overhead_Barbell_Triceps_Extension', 'triceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart. Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position. Keeping your upper arms close to your head and elbows in, perpendicular to…', 60, false),
  ('db-standing-palm-in-one-arm-dumbbell-press', 'Standing Palm-In One-Arm Dumbbell Press', 'Standing_Palm-In_One-Arm_Dumbbell_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip…', 90, true),
  ('db-standing-palms-in-dumbbell-press', 'Standing Palms-In Dumbbell Press', 'Standing_Palms-In_Dumbbell_Press', 'shoulders', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the…', 90, false),
  ('db-standing-palms-up-barbell-behind-the-back-wrist-curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'forearms', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other. You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position. While exhaling, slowly elevate the barbell up by curling your wrist…', 60, false),
  ('db-standing-rope-crunch', 'Standing Rope Crunch', 'Standing_Rope_Crunch', 'abs', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Attach a rope to a high pulley and select an appropriate weight. Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position. Perform the movement by flexing the spine, crunching the weight down as far as you can. Hold the peak contraction for a moment before returning to the starting position.', 60, false),
  ('db-standing-towel-triceps-extension', 'Standing Towel Triceps Extension', 'Standing_Towel_Triceps_Extension', 'triceps', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position. Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping…', 60, false),
  ('db-step-mill', 'Step Mill', 'Step_Mill', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall. Stepmills offer…', 0, false),
  ('db-step-up-with-knee-raise', 'Step-up with Knee Raise', 'Step-up_with_Knee_Raise', 'glutes', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-glutes-compound', 'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position. Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can. Reverse this motion to step…', 90, false),
  ('db-stiff-leg-barbell-good-morning', 'Stiff Leg Barbell Good Morning', 'Stiff_Leg_Barbell_Good_Morning', 'lower_back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same…', 90, false),
  ('db-stiff-legged-barbell-deadlift', 'Stiff-Legged Barbell Deadlift', 'Stiff-Legged_Barbell_Deadlift', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back…', 90, false),
  ('db-straight-bar-bench-mid-rows', 'Straight Bar Bench Mid Rows', 'Straight_Bar_Bench_Mid_Rows', 'back', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position. Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking. After a brief pause, slowly return the bar to the starting position,…', 90, false),
  ('db-straight-raises-on-incline-bench', 'Straight Raises on Incline Bench', 'Straight_Raises_on_Incline_Bench', 'shoulders', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-shoulders-isolation', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position. To begin, raise the barbell out in front of your head while keeping your arms extended. Return to the starting position.', 60, false),
  ('db-stride-jump-crossover', 'Stride Jump Crossover', 'Stride_Jump_Crossover', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.…', 75, false),
  ('db-sumo-deadlift-with-bands', 'Sumo Deadlift with Bands', 'Sumo_Deadlift_with_Bands', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should…', 150, false),
  ('db-sumo-deadlift-with-chains', 'Sumo Deadlift with Chains', 'Sumo_Deadlift_with_Chains', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-hamstrings-compound', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend…', 150, false),
  ('db-supine-chest-throw', 'Supine Chest Throw', 'Supine_Chest_Throw', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent. Begin with the ball on your chest, held with both hands on the bottom. Explode up, extending through the elbow to throw the ball directly above you as high as possible. Catch the ball with both hands as it comes down.', 75, false),
  ('db-supine-one-arm-overhead-throw', 'Supine One-Arm Overhead Throw', 'Supine_One-Arm_Overhead_Throw', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.', 75, true),
  ('db-supine-two-arm-overhead-throw', 'Supine Two-Arm Overhead Throw', 'Supine_Two-Arm_Overhead_Throw', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Lay on the ground on your back with your knees bent. Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.', 75, false),
  ('db-suspended-fallout', 'Suspended Fallout', 'Suspended_Fallout', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Adjust the straps so the handles are at an appropriate height, below waist level. Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position. Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head. Maintain…', 60, false),
  ('db-suspended-push-up', 'Suspended Push-Up', 'Suspended_Push-Up', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Anchor your suspension straps securely to the top of a rack or other object. Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture. Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex. Continue until your elbows break 90…', 90, false),
  ('db-suspended-reverse-crunch', 'Suspended Reverse Crunch', 'Suspended_Reverse_Crunch', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack. Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position. Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt…', 60, false),
  ('db-suspended-row', 'Suspended Row', 'Suspended_Row', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position. Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so. At the completion of the motion pause, and then return to the starting position.', 90, false),
  ('db-suspended-split-squat', 'Suspended Split Squat', 'Suspended_Split_Squat', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Suspend your straps so the handles are 18-30 inches from the floor. Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position. Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the…', 90, false),
  ('db-svend-press', 'Svend Press', 'Svend_Press', 'chest', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Begin in a standing position. Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position. Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion. Pause at the top of the motion, and then…', 90, false),
  ('db-tate-press', 'Tate Press', 'Tate_Press', 'triceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a…', 60, false),
  ('db-trail-running-walking', 'Trail Running/Walking', 'Trail_Running_Walking', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling. A 150 lb person…', 0, false),
  ('db-triceps-overhead-extension-with-rope', 'Triceps Overhead Extension with Rope', 'Triceps_Overhead_Extension_with_Rope', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable. Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position. To perform the movement, extend through…', 60, false),
  ('db-triceps-pushdown-v-bar-attachment', 'Triceps Pushdown - V-Bar Attachment', 'Triceps_Pushdown_-_V-Bar_Attachment', 'triceps', 'cable', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-triceps-isolation', 'Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width. Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.…', 60, false),
  ('db-tuck-crunch', 'Tuck Crunch', 'Tuck_Crunch', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as…', 60, false),
  ('db-two-arm-dumbbell-preacher-curl', 'Two-Arm Dumbbell Preacher Curl', 'Two-Arm_Dumbbell_Preacher_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells…', 60, false),
  ('db-two-arm-kettlebell-clean', 'Two-Arm Kettlebell Clean', 'Two-Arm_Kettlebell_Clean', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so. Lower the kettlebells back to the starting position and repeat.', 90, false),
  ('db-two-arm-kettlebell-jerk', 'Two-Arm Kettlebell Jerk', 'Two-Arm_Kettlebell_Jerk', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once…', 90, false),
  ('db-two-arm-kettlebell-military-press', 'Two-Arm Kettlebell Military Press', 'Two-Arm_Kettlebell_Military_Press', 'shoulders', 'kettlebell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-shoulders-compound', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats,…', 90, false),
  ('db-underhand-cable-pulldowns', 'Underhand Cable Pulldowns', 'Underhand_Cable_Pulldowns', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width. As you have both arms extended in front of you…', 90, false),
  ('db-upright-cable-row', 'Upright Cable Row', 'Upright_Cable_Row', 'traps', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-traps-compound', 'Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the cable bar as you exhale. The bar…', 90, false),
  ('db-upright-row-with-bands', 'Upright Row - With Bands', 'Upright_Row_-_With_Bands', 'traps', 'band', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-traps-compound', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles…', 90, false),
  ('db-v-bar-pullup', 'V-Bar Pullup', 'V-Bar_Pullup', 'back', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles. Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly…', 90, false),
  ('db-vertical-swing', 'Vertical Swing', 'Vertical_Swing', 'hamstrings', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'jump', 'Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up. Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly. Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head. As you land, absorb the impact through your legs and draw…', 75, false),
  ('db-walking-treadmill', 'Walking, Treadmill', 'Walking_Treadmill', 'quads', 'cardio', 'time', array['time']::text[], 'compound', 'cardio', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than…', 0, false),
  ('db-weighted-ball-hyperextension', 'Weighted Ball Hyperextension', 'Weighted_Ball_Hyperextension', 'lower_back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-lower_back-compound', 'To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position. Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement. Hold the contraction on…', 90, false),
  ('db-weighted-ball-side-bend', 'Weighted Ball Side Bend', 'Weighted_Ball_Side_Bend', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball. Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head. Place your left arm across your torso so that…', 60, false),
  ('db-weighted-bench-dip', 'Weighted Bench Dip', 'Weighted_Bench_Dip', 'triceps', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-triceps-compound', 'For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended. The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be…', 90, false),
  ('db-weighted-crunches', 'Weighted Crunches', 'Weighted_Crunches', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle. Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position. Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor. At the top of…', 60, false),
  ('db-weighted-pull-ups', 'Weighted Pull Ups', 'Weighted_Pull_Ups', 'back', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip. You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will…', 90, false),
  ('db-weighted-sit-ups-with-bands', 'Weighted Sit-Ups - With Bands', 'Weighted_Sit-Ups_-_With_Bands', 'abs', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-abs-isolation', 'Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them. Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your…', 60, false),
  ('db-weighted-squat', 'Weighted Squat', 'Weighted_Squat', 'quads', 'other', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out. Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting…', 90, false),
  ('db-wide-stance-barbell-squat', 'Wide Stance Barbell Squat', 'Wide_Stance_Barbell_Squat', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same…', 90, false),
  ('db-wide-stance-stiff-legs', 'Wide Stance Stiff Legs', 'Wide_Stance_Stiff_Legs', 'hamstrings', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'olympic', 'Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position. Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight…', 150, false),
  ('db-wide-grip-barbell-bench-press', 'Wide-Grip Barbell Bench Press', 'Wide-Grip_Barbell_Bench_Press', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle…', 90, false),
  ('db-wide-grip-decline-barbell-bench-press', 'Wide-Grip Decline Barbell Bench Press', 'Wide-Grip_Decline_Barbell_Bench_Press', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you…', 90, false),
  ('db-wide-grip-decline-barbell-pullover', 'Wide-Grip Decline Barbell Pullover', 'Wide-Grip_Decline_Barbell_Pullover', 'chest', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-chest-compound', 'Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms. When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting…', 90, false),
  ('db-wide-grip-pulldown-behind-the-neck', 'Wide-Grip Pulldown Behind The Neck', 'Wide-Grip_Pulldown_Behind_The_Neck', 'back', 'cable', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder…', 90, false),
  ('db-wide-grip-rear-pull-up', 'Wide-Grip Rear Pull-Up', 'Wide-Grip_Rear_Pull-Up', 'back', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-back-compound', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position. Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while…', 90, false),
  ('db-wide-grip-standing-barbell-curl', 'Wide-Grip Standing Barbell Curl', 'Wide-Grip_Standing_Barbell_Curl', 'biceps', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully…', 60, false),
  ('db-wind-sprints', 'Wind Sprints', 'Wind_Sprints', 'abs', 'bodyweight', 'bodyweight_reps', array['weight','reps']::text[], 'compound', 'db-abs-compound', 'Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position. Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3 Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible. Continue alternating between legs until the set is complete.', 90, false),
  ('db-wrist-roller', 'Wrist Roller', 'Wrist_Roller', 'forearms', 'other', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-forearms-isolation', 'To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart. Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position. Rotate one wrist at a time in…', 60, false),
  ('db-wrist-rotations-with-straight-bar', 'Wrist Rotations with Straight Bar', 'Wrist_Rotations_with_Straight_Bar', 'forearms', 'barbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'rotation', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position. Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure. Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion…', 60, false),
  ('db-yoke-walk', 'Yoke Walk', 'Yoke_Walk', 'quads', 'other', 'custom', array['weight','distance']::text[], 'compound', 'complex', 'The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects. Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels. Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position.…', 90, false),
  ('db-zercher-squats', 'Zercher Squats', 'Zercher_Squats', 'quads', 'barbell', 'weight_reps', array['weight','reps']::text[], 'compound', 'db-quads-compound', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm. Lift the bar up so that it is resting on…', 90, false),
  ('db-zottman-curl', 'Zottman Curl', 'Zottman_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Make sure the palms of the hands are facing each other. This will be your starting position. While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated…', 60, false),
  ('db-zottman-preacher-curl', 'Zottman Preacher Curl', 'Zottman_Preacher_Curl', 'biceps', 'dumbbell', 'weight_reps', array['weight','reps']::text[], 'isolation', 'db-biceps-isolation', 'Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position. As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully…', 60, false)
